public class RecipeSchemaProvider {
	private static final Map<String, RecipeSchema> SCHEMAS = new HashMap<>();

	public static void registerSchema(String type, RecipeSchema schema) {
		SCHEMAS.put(type, schema);
	}

	public static RecipeSchema getSchema(String type) {
		return SCHEMAS.get(type);
	}

	public static void init() {
		registerSchema("shaped", new ShapedRecipeSchema());
		registerSchema("shapeless", new ShapelessRecipeSchema());
		registerSchema("smelting", new CookingRecipeSchema("smelting"));
		registerSchema("blasting", new CookingRecipeSchema("blasting"));
		registerSchema("smoking", new CookingRecipeSchema("smoking"));
		registerSchema("campfire_cooking", new CookingRecipeSchema("campfire_cooking"));
		registerSchema("smithing_transform", new SmithingTransformRecipeSchema());
		registerSchema("stonecutting", new StonecuttingRecipeSchema());
	}

	public static void registerDefaults() {
		registerSchema("kubejs:shaped", new KubeShapedRecipeSchema());
		registerSchema("kubejs:shapeless", new KubeShapelessRecipeSchema());
		registerSchema("kubejs:cooking", new KubeCookingRecipeSchema());
	}
}
